// ?showNotificationBox@@YAXVAsciiString@@VUnicodeString@@@Z
// partial score=0.35 date=2026-09-27
// ?showNotificationBox@@YAXVAsciiString@@VUnicodeString@@@Z carries.
//
// THE LIFT'S SIGNATURE IS WRONG.  The body takes ONE argument, a BuddyMessage
// BY VALUE, laid out in place (24 bytes = 6 dwords) in the caller's frame.
// Proof, three independent ways:
//   1. The only two declarations of the symbol in the tree are by value --
//      game/.../WOLBuddyResponses.cpp:309 and
//      game/.../Rva004EDED0BuddyMessageNotification.cpp:75:
//          extern "C" void bfme_showNotificationBox_4ECD10(BuddyMessage);
//   2. The LAST call in the body is ~BuddyMessage (0x004EA4B0, via ILT
//      0x00021445) entered with `lea ecx,[esp+0x9c]` -- `this` is the
//      ARGUMENT SLOT ITSELF, so the object lives in the arg area, not behind
//      a pointer.  A pointer parameter would be `mov ecx,[esp+...]`.
//   3. Every call site (0x004EDF28 in Rva004EDED0, 0x004EE30A / 0x004EEB7D /
//      0x004EEE21 / 0x004EF1ED / 0x004EF2BA, all through ILT 0x00037FC9)
//      builds exactly 0x18 bytes: `sub esp,0x14` (the first five fields as one
//      block) plus a 4-byte UnicodeString temp constructed at the top, and
//      cleans it with `add esp,0x18`.
//
// ARG BLOCK MAP (fixed-frame disp at esp = E, E = esp just after `push ebx`;
// 0x8c = saved fs, 0x94 = the pushed -1, which MSVC 7.1 reuses as the EH
// scope-state byte, 0x98 = return address, so the arg block is 0x9c..0xb3):
//     0x9c  m_message        (UnicodeString)  <- constructed at the top by the
//                                                  caller, index 0
//     0xa0  m_recipientNick  (AsciiString)
//     0xa4  m_recipientID    (int)
//     0xa8  m_senderNick     (AsciiString)
//     0xac  m_senderID       (int)
//     0xb0  m_timestamp      (UnsignedInt)
// The block copy of the first five fields keeps declaration order, so index 0
// is the last field: that is the only assignment consistent with the two
// null-checked `str()` reads at +0x029 ([0xb0] = m_recipientNick.str()) and
// +0x047 (fixed [0xa8] = m_senderNick.str()).
//
// FRAME: `sub esp,0x88` + `push ebx`, no callee-saved register besides ebx.
// ebx is the zero sentinel (`xor ebx,ebx`) that every `cmp eax,ebx` /
// `cmp ecx,ebx` null test uses, and it doubles as the FALSE for the 0x12F4240
// byte store.  ONE EH scope-table entry, state byte at fixed 0x94, states in
// source order 0,1,2,3,4,5,6,7 with -1 on the normal exit path.  The `jne`
// at +0x09d lands on +0x1f0, i.e. the two arms of the 0x005127A0 test share
// the destructor tail and are told apart only by the state byte.
//
// GLOBALS
//   0x012ED668  TheAudio                  vtable +0x44 = addAudioEvent
//   0x012F147C  TheGameText               vtable +0x28 = fetch(label, Bool*)
//   0x012F4240  lastNotificationWasStatus (byte)   (WOLBuddyOverlay.cpp statics)
//   0x012F4244  numOnlineInNotification   (dword)
//   0x012B9220  pushed twice into 0x005127A0; NOT YET IDENTIFIED
//
// STRING LITERALS
//   0x011021E4  L"["                       (wide)
//   0x01102480  "Buddy:MessageNotification"
//   0x011024A0  "GUIMessageReceived"
//   0x01336E50  AsciiString::TheEmptyString
//
// THIS IS NOT the WOLBuddyOverlay.cpp `showNotificationBox` that the tree
// carries.  That one opens a window layout, calls hide() and
// GadgetButtonSetText(); this body never touches the window manager.  What it
// does, in address order:
//
//   +0x000  SEH prologue; ebx = 0; state 0
//   +0x01e  state = 0 (dword 0 into the state slot)
//   +0x029  push message.m_recipientNick.str()   (null-checked, m_data+8)
//   +0x047  push message.m_senderNick.str()      (null-checked, m_data+8)
//   +0x05d  reserve a 4-byte slot; construct a UnicodeString in it from L"["
//           (0x00888DE0) and remember the slot in a local for the EH path
//   +0x073  that temp .format(<local>)            (0x00889190, one arg)
//   +0x078  ecx = 0x012B9220; push ecx; push ecx
//   +0x08e  copy-construct a StringBase<wchar_t> temp from a local (0x00888400)
//   +0x093  call 0x005127A0 (Rva005127A0Forward), test al
//   +0x09d  if (al) goto +0x1f0  (skip the AudioEventRTS below)
//   +0x0a3  AsciiString temp("GUIMessageReceived")   (0x00888BC0)
//   +0x0b1  AudioEventRTS evt(temp, 2);               (0x000B2CC0 via 0x25306)
//   +0x0c9  ~AsciiString temp                          (0x00887940); state 4
//   +0x0da  if (TheAudio) TheAudio->addAudioEvent(&evt)
//   +0x0ee  copy-construct a local from a message field (0x00888400); state 5
//   +0x107  while (local->length > 0x1e) local.removeLastChar();  (0x00888840)
//                                                    state 6 -- a CAP at 30 chars
//   +0x13c  push <another message field>.str()  (null-checked)
//   +0x151  TheGameText->fetch("Buddy:MessageNotification", NULL)
//   +0x170  that result .format(<the trimmed local>)
//   +0x183  lastNotificationWasStatus = 0; numOnlineInNotification = 0
//   +0x18f  copy-construct a StringBase<wchar_t> temp from the local
//   +0x194  reserve a 4-byte slot; copy-construct AsciiString(0x01336E50)
//           into it (0x00887B60); state 7
//   +0x1b5  Rva004EBA70NotificationDispatch(theEmpty, temp)   (0x004EBA70)
//   +0x1bd  ~StringBase<wchar_t> local                        (0x008881D0); state 5
//   +0x1ce  ~StringBase<wchar_t> local                        (0x008881D0); state 4
//   +0x1df  ~AudioEventRTS                                    (0x000B31F0); state 1
//   +0x1f0  ~StringBase<wchar_t> local                        (0x008881D0); state 0
//   +0x200  ~BuddyMessage(message)                            (0x004EA4B0); state -1
//   +0x217  restore fs, pop ebx, `add esp,0x94`, ret
//
// So BFME replaced the window-layout notification with a cap-at-30-characters
// message fetch plus the game-mode dispatch at 0x004EBA70, and the two
// 0x005127A0 arms are the two sounds/paths.
//
// WHAT IS STILL MISSING (why this is a bank and not a landing)
//   * the statement that owns the L"[" temp at +0x05d and the two pushed
//     `.str()` values it sits between -- the pushes are consumed by the batch
//     `add esp,0x10` at +0x07e, so the reading of that block as a single
//     `format` is unproven;
//   * which message field the +0x0ee copy and the +0x13c `.str()` read (the
//     fixed-frame slot arithmetic at those two points depends on whether
//     0x00889190 / 0x00887B60 / 0x000B2CC0 self-clean, and they have BOTH
//     `ret` and `ret N` exits);
//   * 0x012B9220.
// Note 0x00888DE0 is `ret 4` (self-cleaning) while 0x00889190 is not, which is
// what makes `add esp,0x10` at +0x07e balance four pushes.

class StringBase
{
public:
	StringBase(const StringBase<T> &);
	~StringBase();
};

class AsciiString
{
public:
	AsciiString(const AsciiString &that)
	{
		((StringBase<char> *)this)->StringBase<char>::StringBase(
			*(const StringBase<char> *)&that);
	}
	~AsciiString();

private:
	void *m_data;
};

class UnicodeString
{
public:
	UnicodeString(const wchar_t *);
	UnicodeString(const UnicodeString &that)
	{
		((StringBase<unsigned short> *)this)->StringBase<unsigned short>::StringBase(
			*(const StringBase<unsigned short> *)&that);
	}
	UnicodeString &format(const UnicodeString &that);
	~UnicodeString();

private:
	void *m_data;
};

class BuddyMessage
{
public:
	unsigned int m_timestamp;
	int m_senderID;
	AsciiString m_senderNick;
	int m_recipientID;
	AsciiString m_recipientNick;
	UnicodeString m_message;
};

